void GetExtensionViews(const v8::FunctionCallbackInfo<v8::Value>& args) {
  v8::Isolate* isolate = args.GetIsolate();
  v8::Local<v8::Context> context = isolate->GetCurrentContext();

  // Check if the correct number of arguments are provided
  if (args.Length() != 2 || !args[0]->IsString() || !args[1]->IsString()) {
    isolate->ThrowException(v8::Exception::TypeError(
        v8::String::NewFromUtf8(isolate, "Invalid arguments: expected two strings (browser window ID and view type).").ToLocalChecked()));
    return;
  }

  v8::String::Utf8Value browser_window_id(isolate, args[0]);
  v8::String::Utf8Value view_type_str(isolate, args[1]);

  // Determine view type based on input string
  ViewType view_type = kInvalidView;
  if (std::string(*view_type_str) == "main") {
    view_type = kMainView;
  } else if (std::string(*view_type_str) == "iframe") {
    view_type = kIframeView;
  }

  if (view_type == kInvalidView) {
    isolate->ThrowException(v8::Exception::TypeError(
        v8::String::NewFromUtf8(isolate, "Invalid view type. Expected 'main' or 'iframe'.").ToLocalChecked()));
    return;
  }

  // Retrieve the extension ID
  std::string extension_id = GetExtensionIdFromWindowId(*browser_window_id);
  if (extension_id.empty()) {
    args.GetReturnValue().Set(v8::Array::New(isolate, 0));
    return;
  }

  // Fetch relevant frames and filter out iframes if needed
  std::vector<ViewInfo> views = GetViewsByExtension(extension_id);
  std::vector<ViewInfo> filtered_views;

  for (const auto& view : views) {
    if (view.type == kMainView || view.type != kIframeView) {
      filtered_views.push_back(view);
    }
  }

  // Construct the V8 array of main views
  v8::Local<v8::Array> result_array = v8::Array::New(isolate, filtered_views.size());
  for (size_t i = 0; i < filtered_views.size(); ++i) {
    v8::Local<v8::Object> view_obj = v8::Object::New(isolate);
    view_obj->Set(context, v8::String::NewFromUtf8(isolate, "id").ToLocalChecked(),
                  v8::Integer::New(isolate, filtered_views[i].id)).Check();
    view_obj->Set(context, v8::String::NewFromUtf8(isolate, "type").ToLocalChecked(),
                  v8::String::NewFromUtf8(isolate, ViewTypeToString(filtered_views[i].type)).ToLocalChecked()).Check();
    result_array->Set(context, i, view_obj).Check();
  }

  args.GetReturnValue().Set(result_array);
}

void GetExtensionViews(const v8::FunctionCallbackInfo<v8::Value>& args) {
  v8::Isolate* isolate = args.GetIsolate();
  v8::HandleScope handle_scope(isolate);

  if (args.Length() != 2 || !args[0]->IsNumber() || !args[1]->IsString()) {
    isolate->ThrowException(v8::Exception::TypeError(
        v8::String::NewFromUtf8(isolate, "Invalid arguments").ToLocalChecked()));
    return;
  }

  int window_id = args[0].As<v8::Number>()->Value();
  v8::String::Value view_type_str(isolate, args[1]);
  std::string view_type(*view_type_str);

  std::string extension_id = GetExtensionID(window_id);
  if (extension_id.empty()) {
    args.GetReturnValue().Set(v8::Array::New(isolate, 0));
    return;
  }

  std::vector<FrameInfo> frames = GetFramesForExtension(extension_id);
  std::vector<FrameInfo> filtered_frames;

  for (const auto& frame : frames) {
    if (!frame.is_iframe) {
      filtered_frames.push_back(frame);
    }
  }

  v8::Local<v8::Array> result = v8::Array::New(isolate, filtered_frames.size());
  for (size_t i = 0; i < filtered_frames.size(); ++i) {
    v8::Local<v8::Object> frame_obj = v8::Object::New(isolate);
    frame_obj->Set(
        isolate->GetCurrentContext(), v8::String::NewFromUtf8(isolate, "id").ToLocalChecked(),
        v8::Integer::New(isolate, filtered_frames[i].id));
    frame_obj->Set(
        isolate->GetCurrentContext(), v8::String::NewFromUtf8(isolate, "type").ToLocalChecked(),
        v8::String::NewFromUtf8(isolate, filtered_frames[i].type.c_str()).ToLocalChecked());
    result->Set(isolate->GetCurrentContext(), i, frame_obj).Check();
  }

  args.GetReturnValue().Set(result);
}

void GetExtensionViews(const v8::FunctionCallbackInfo<v8::Value>& args) {
  v8::Isolate* isolate = args.GetIsolate();
  v8::Local<v8::Context> context = isolate->GetCurrentContext();

  if (args.Length() != 2 || !args[0]->IsNumber() || !args[1]->IsString()) {
    isolate->ThrowException(v8::Exception::TypeError(
        v8::String::NewFromUtf8(isolate, "Invalid arguments: expected window ID and view type string").ToLocalChecked()));
    return;
  }

  int window_id = args[0]->Int32Value(context).ToChecked();
  v8::String::Utf8Value view_type_str(isolate, args[1]);
  std::string view_type(*view_type_str);

  std::string extension_id = GetExtensionIdFromWindow(window_id);
  if (extension_id.empty()) {
    args.GetReturnValue().Set(v8::Array::New(isolate, 0));
    return;
  }

  std::vector<content::WebContents*> web_contents_list =
      GetWebContentsForExtension(extension_id);

  std::vector<content::WebContents*> filtered_views;
  for (auto* web_contents : web_contents_list) {
    if (web_contents->GetOuterWebContents() == nullptr &&
        web_contents->GetParent() == nullptr) {
      filtered_views.push_back(web_contents);
    }
  }

  v8::Local<v8::Array> result_array = v8::Array::New(isolate, filtered_views.size());
  for (size_t i = 0; i < filtered_views.size(); ++i) {
    result_array->Set(context, i, GetWebContentsHandle(filtered_views[i])).Check();
  }

  args.GetReturnValue().Set(result_array);
}

